public class ExpressionTokenizerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("NUMBER matches digits", 2, ExpressionTokenizer.TokenKind.NUMBER.matchLength("12+3", 0));
        check("NUMBER at an operator", 0, ExpressionTokenizer.TokenKind.NUMBER.matchLength("12+3", 2));
        check("NAME stops at a digit", 4, ExpressionTokenizer.TokenKind.NAME.matchLength("ab_c1", 0));
        check("NAME at a digit", 0, ExpressionTokenizer.TokenKind.NAME.matchLength("1abc", 0));
        check("OPERATOR matches one char", 1, ExpressionTokenizer.TokenKind.OPERATOR.matchLength("a+b", 1));
        check("OPERATOR at a letter", 0, ExpressionTokenizer.TokenKind.OPERATOR.matchLength("a+b", 0));
        check("PAREN matches one char", 1, ExpressionTokenizer.TokenKind.PAREN.matchLength("(x)", 2));

        checkCall("tokenize a mixed expression",
                "[NUMBER:12, OPERATOR:+, NAME:ab, OPERATOR:*, PAREN:(, NUMBER:3, PAREN:)]",
                () -> ExpressionTokenizer.tokenize("12 + ab*(3)").toString());
        checkCall("underscored name then number", "[NAME:_total_, NUMBER:1]",
                () -> ExpressionTokenizer.tokenize("_total_1").toString());
        checkCall("only spaces", "[]", () -> ExpressionTokenizer.tokenize("   ").toString());
        checkCall("leading and trailing spaces", "[NUMBER:7, OPERATOR:-, NUMBER:2]",
                () -> ExpressionTokenizer.tokenize("  7 - 2  ").toString());
        checkCall("unknown character", "threw IllegalArgumentException",
                () -> ExpressionTokenizer.tokenize("a $ b").toString());
        done();
    }
}

