import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Complete ExpressionTokenizer.
 *
 * Each TokenKind constant implements matchLength(text, pos): how many
 * characters of text, starting at pos, this kind matches. 0 means no match.
 * - NUMBER matches a run of digits ("12+3" at 0 -> 2, at 2 -> 0)
 * - NAME matches a run of letters and underscores ("ab_c1" at 0 -> 4, because
 *   the digit ends the run)
 * - OPERATOR matches exactly one of + - * / (length 1 or 0)
 * - PAREN matches exactly one of ( ) (length 1 or 0)
 *
 * tokenize(text) scans left to right:
 * - spaces are skipped
 * - otherwise it tries the kinds in declaration order with values() and takes
 *   the FIRST one whose matchLength is above 0, adding the token as
 *   kind.name() + ":" + the matched text, then jumps past it
 * - a character no kind matches means
 *   throw new IllegalArgumentException("unexpected character: " + c)
 *
 * Example: tokenize("12 + ab*(3)") ->
 *   [NUMBER:12, OPERATOR:+, NAME:ab, OPERATOR:*, PAREN:(, NUMBER:3, PAREN:)]
 */
public class ExpressionTokenizer {

    public enum TokenKind {

        NUMBER {
            @Override
            public int matchLength(String text, int pos) {
                int end = pos;
                while (end < text.length() && Character.isDigit(text.charAt(end))) {
                    end++;
                }
                return end - pos;
            }
        },
        NAME {
            @Override
            public int matchLength(String text, int pos) {
                int end = pos;
                while (end < text.length()
                        && (Character.isLetter(text.charAt(end)) || text.charAt(end) == '_')) {
                    end++;
                }
                return end - pos;
            }
        },
        OPERATOR {
            @Override
            public int matchLength(String text, int pos) {
                return "+-*/".indexOf(text.charAt(pos)) >= 0 ? 1 : 0;
            }
        },
        PAREN {
            @Override
            public int matchLength(String text, int pos) {
                return "()".indexOf(text.charAt(pos)) >= 0 ? 1 : 0;
            }
        };

        public abstract int matchLength(String text, int pos);
    }

    public static List<String> tokenize(String text) {
        List<String> tokens = new ArrayList<>();
        int pos = 0;
        while (pos < text.length()) {
            char c = text.charAt(pos);
            if (c == ' ') {
                pos++;
                continue;
            }
            int matched = 0;
            for (TokenKind kind : TokenKind.values()) {
                int length = kind.matchLength(text, pos);
                if (length > 0) {
                    tokens.add(kind.name() + ":" + text.substring(pos, pos + length));
                    matched = length;
                    break;
                }
            }
            if (matched == 0) {
                throw new IllegalArgumentException("unexpected character: " + c);
            }
            pos += matched;
        }
        return tokens;
    }
}
